      if (key === 'processing') return `<section class="commerce-section"><h2>Cancel</h2><p>The store is preparing this order. To cancel it, ask the store.</p><div class="form-actions">${link('messages', 'Ask the store to cancel', { order: order.id, store: order.merchantStoreId }, 'platform-button is-secondary')}</div></section>`;
