      const account = row => { const handle = String(row.handle || '').replace(/^@/, ''); return /^[A-Za-z0-9._-]{1,60}$/.test(handle) ? `<a href="${e(SCALE_URLS[row.platform](handle))}" target="_blank" rel="noopener noreferrer">${e(SCALE_NAMES[row.platform])} @${e(handle)}<span class="sr-only"> (opens in a new tab)</span></a>` : `${e(SCALE_NAMES[row.platform])} ${e(row.handle)}`; };
